import sys, os, json
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from lib import *
M = "/_plugins/_ml"
H = "http://127.0.0.1:18080"
SRC = "compat-ml-src"
nd = "".join(json.dumps(x) + "\n" for i in range(40) for x in ({"index": {"_id": str(i)}}, {"x": float(i % 4), "y": float((i // 4) % 3), "g": "k" + str(i % 2)}))
conn = lambda name, **kw: dict({"name": name, "description": "d", "version": "1", "protocol": "http", "parameters": {"endpoint": "127.0.0.1:18080"}, "credential": {"k": "v"},
    "actions": [{"action_type": "predict", "method": "POST", "url": H + "/json", "headers": {"x": "y"}, "request_body": "{\"input\":\"${parameters.input}\"}"}]}, **kw)
steps = [
 step("register model group", "POST", M + "/model_groups/_register", {"name": "compat-g1", "description": "d"}, capture={"g": "/model_group_id"}),
 step("register duplicate model group", "POST", M + "/model_groups/_register", {"name": "compat-g1", "description": "d"}),
 step("register group without name", "POST", M + "/model_groups/_register", {"description": "d"}),
 step("register group with access mode", "POST", M + "/model_groups/_register", {"name": "compat-g2", "description": "d", "access_mode": "public"}, capture={"g2": "/model_group_id"}),
 step("get model group", "GET", M + "/model_groups/{g}"),
 step("get missing model group", "GET", M + "/model_groups/nope"),
 step("update model group", "PUT", M + "/model_groups/{g}", {"description": "changed"}),
 step("update missing model group", "PUT", M + "/model_groups/nope", {"description": "changed"}),
 step("search model groups", "POST", M + "/model_groups/_search", {"query": {"match_all": {}}, "sort": [{"name.keyword": "asc"}]}),
 step("create connector", "POST", M + "/connectors/_create", conn("compat-c1"), capture={"c": "/connector_id"}),
 step("create connector with untrusted url", "POST", M + "/connectors/_create", conn("compat-c2", actions=[{"action_type": "predict", "method": "POST", "url": "http://203.0.113.9/x", "request_body": "{}"}])),
 step("create connector without actions", "POST", M + "/connectors/_create", conn("compat-c3", actions=[]), capture={"c3": "/connector_id"}),
 step("create connector bad protocol", "POST", M + "/connectors/_create", conn("compat-c4", protocol="carrier")),
 step("create connector without name", "POST", M + "/connectors/_create", {k: v for k, v in conn("x").items() if k != "name"}),
 step("create connector duplicate name", "POST", M + "/connectors/_create", conn("compat-c1"), capture={"c_dup": "/connector_id"}),
 step("get connector", "GET", M + "/connectors/{c}"),
 step("get missing connector", "GET", M + "/connectors/nope"),
 step("update connector", "PUT", M + "/connectors/{c}", {"description": "changed"}),
 step("get updated connector", "GET", M + "/connectors/{c}"),
 step("search connectors", "POST", M + "/connectors/_search", {"query": {"match_all": {}}, "sort": [{"name.keyword": "asc"}]}),
 step("register remote model", "POST", M + "/models/_register", {"name": "compat-m1", "function_name": "remote", "description": "d", "connector_id": "{c}", "model_group_id": "{g}"}, capture={"m": "/model_id", "t": "/task_id"}),
 step("get register task", "GET", M + "/tasks/{t}", poll=("/state", "COMPLETED", 60)),
 step("get model", "GET", M + "/models/{m}", poll=("/model_state", "REGISTERED", 30), wait=3),
 step("get missing model", "GET", M + "/models/nope"),
 step("predict on an undeployed model", "POST", M + "/models/{m}/_predict", {"parameters": {"input": "hi"}}),
 step("deploy model", "POST", M + "/models/{m}/_deploy", capture={"dt": "/task_id"}),
 step("get deploy task", "GET", M + "/tasks/{dt}", poll=("/state", "COMPLETED", 60)),
 step("get deployed model", "GET", M + "/models/{m}", poll=("/model_state", "DEPLOYED", 60)),
 step("predict", "POST", M + "/models/{m}/_predict", {"parameters": {"input": "hi"}}),
 step("predict without parameters", "POST", M + "/models/{m}/_predict", {}),
 step("predict with unknown parameter", "POST", M + "/models/{m}/_predict", {"parameters": {"nope": "x"}}),
 step("predict unified path", "POST", M + "/_predict/remote/{m}", {"parameters": {"input": "hi"}}),
 step("profile models", "GET", M + "/profile/models"),
 step("profile model", "GET", M + "/profile/models/{m}"),
 step("stats by name", "GET", M + "/stats/ml_connector_count,ml_model_count"),
 step("stats of unknown name", "GET", M + "/stats/nope"),
 step("update model", "PUT", M + "/models/{m}", {"description": "changed"}),
 step("search models", "POST", M + "/models/_search", {"query": {"match_all": {}}, "_source": {"excludes": ["model_content"]}, "sort": [{"name.keyword": "asc"}]}),
 step("search tasks", "POST", M + "/tasks/_search", {"size": 0, "query": {"match_all": {}}}),
 step("delete connector in use", "DELETE", M + "/connectors/{c}"),
 step("delete deployed model", "DELETE", M + "/models/{m}"),
 step("undeploy model", "POST", M + "/models/{m}/_undeploy"),
 step("undeploy again", "POST", M + "/models/{m}/_undeploy"),
 step("delete model", "DELETE", M + "/models/{m}"),
 step("delete model again", "DELETE", M + "/models/{m}"),
 step("register remote model with inline connector", "POST", M + "/models/_register", {"name": "compat-m2", "function_name": "remote", "description": "d", "connector": conn("compat-inline")}, capture={"m2": "/model_id"}),
 step("register remote model without connector", "POST", M + "/models/_register", {"name": "compat-m3", "function_name": "remote", "description": "d"}),
 step("register unknown function", "POST", M + "/models/_register", {"name": "compat-m4", "function_name": "nope", "description": "d"}),
 step("register without name", "POST", M + "/models/_register", {"function_name": "remote"}),
 step("register with unknown group", "POST", M + "/models/_register", {"name": "compat-m5", "function_name": "remote", "connector_id": "{c}", "model_group_id": "nope"}),
 step("register text embedding from a url that is not allowed", "POST", M + "/models/_register", {"name": "compat-m6", "version": "1.0.0", "model_format": "ONNX", "function_name": "TEXT_EMBEDDING", "url": "http://127.0.0.1:18080/200", "model_content_hash_value": "00", "model_config": {"model_type": "bert", "embedding_dimension": 3, "framework_type": "sentence_transformers"}}),
 step("register pretrained model not available", "POST", M + "/models/_register", {"name": "huggingface/sentence-transformers/nope", "version": "1.0.1", "model_format": "TORCH_SCRIPT"}),
 step("delete inline model", "DELETE", M + "/models/{m2}"),
 step("kmeans train", "POST", M + "/_train/kmeans", {"parameters": {"centroids": 2, "iterations": 10, "distance_type": "EUCLIDEAN"}, "input_query": {"_source": ["x", "y"], "size": 40, "query": {"match_all": {}}}, "input_index": [SRC]}, capture={"km": "/model_id"}),
 step("kmeans train without input", "POST", M + "/_train/kmeans", {"parameters": {"centroids": 2}}),
 step("kmeans train with unknown index", "POST", M + "/_train/kmeans", {"parameters": {"centroids": 2}, "input_index": ["compat-ml-nope"], "input_query": {"query": {"match_all": {}}, "size": 5}}),
 step("train unknown algorithm", "POST", M + "/_train/nope", {"parameters": {}}),
 step("train and predict kmeans", "POST", M + "/_train_predict/kmeans", {"parameters": {"centroids": 2, "iterations": 10, "distance_type": "EUCLIDEAN"}, "input_query": {"_source": ["x", "y"], "size": 6, "query": {"match_all": {}}, "sort": [{"x": "asc"}, {"y": "asc"}]}, "input_index": [SRC]}),
 step("execute sample calculator", "POST", M + "/_execute/local_sample_calculator", {"operation": "sum", "input_data": [1.0, 2.0, 3.0]}),
 step("execute max", "POST", M + "/_execute/local_sample_calculator", {"operation": "max", "input_data": [1.0, 2.0, 3.0]}),
 step("execute unknown operation", "POST", M + "/_execute/local_sample_calculator", {"operation": "nope", "input_data": [1.0]}),
 step("execute unknown algorithm", "POST", M + "/_execute/nope", {}),
 step("register agent", "POST", M + "/agents/_register", {"name": "compat-a1", "type": "flow", "description": "d", "tools": [{"type": "MLModelTool", "parameters": {"model_id": "nope"}}]}, capture={"a": "/agent_id"}),
 step("register agent without tools", "POST", M + "/agents/_register", {"name": "compat-a2", "type": "flow", "description": "d"}, capture={"a2": "/agent_id"}),
 step("register agent bad type", "POST", M + "/agents/_register", {"name": "compat-a3", "type": "nope", "description": "d", "tools": []}),
 step("get agent", "GET", M + "/agents/{a}"),
 step("search agents", "POST", M + "/agents/_search", {"query": {"match_all": {}}}),
 step("delete agent", "DELETE", M + "/agents/{a}"),
 step("get deleted agent", "GET", M + "/agents/{a}"),
 step("list tools", "GET", M + "/tools"),
 step("get tool", "GET", M + "/tools/MLModelTool"),
 step("create memory", "POST", M + "/memory", {"name": "compat-mem"}, capture={"mem": "/memory_id"}),
 step("get memory", "GET", M + "/memory/{mem}"),
 step("delete memory", "DELETE", M + "/memory/{mem}"),
 step("delete connector", "DELETE", M + "/connectors/{c}"),
 step("delete duplicate connector", "DELETE", M + "/connectors/{c_dup}"),
 step("delete connector without actions", "DELETE", M + "/connectors/{c3}"),
 step("delete agent without tools", "DELETE", M + "/agents/{a2}"),
 step("delete kmeans model", "DELETE", M + "/models/{km}"),
 step("delete model group", "DELETE", M + "/model_groups/{g}"),
 step("get deleted model group", "GET", M + "/model_groups/{g}"),
 step("settings", "GET", "/_cluster/settings", query={"include_defaults": "true", "filter_path": "defaults.plugins.ml_commons.model_access_control_enabled,defaults.plugins.ml_commons.max_ml_task_per_node,defaults.plugins.ml_commons.only_run_on_ml_node"}),
]
VOL = ["took", "_seq_no", "_primary_term", "create_time", "last_update_time", "last_updated_time", "last_registered_time", "last_deployed_time", "last_undeployed_time", "id", "worker_node", "worker_nodes", "planning_worker_nodes", "current_worker_node_count", "planning_worker_node_count", "model_version", "_version", "ml_deployed_model_count", "node_id", "total_model_count", "ml_request_count", "ml_failure_count", "ml_executing_task_count", "ml_total_model_count", "ml_total_failure_count", "ml_total_request_count", "ml_connector_count", "ml_model_count", "predict_request_count", "model_count", "request_count", "failure_count", "execute_request_count", "execute_failure_count", "training_request_count", "training_failure_count", "value", "ml_circuit_breaker_trigger_count", "ml_deployed_model_count", "ml_jvm_heap_usage", "time_since_last_seen", "predict_request_stats", "memory_id", "created_time", "updated_time", "access", "owner", "backend_roles", "last_access_time", "total_chunk_count", "task_id", "error", "p50", "p90", "p99", "max", "average", "min", "predictor"]
cl = [("DELETE", "/" + SRC, None, {"ignore_unavailable": "true"})] + [("POST", "/" + i + "/_delete_by_query", {"query": {"match_all": {}}}, {"refresh": "true", "ignore_unavailable": "true"}) for i in (".plugins-ml-model-group", ".plugins-ml-connector", ".plugins-ml-model", ".plugins-ml-task", ".plugins-ml-agent", ".plugins-ml-memory-meta")]
settings = {"persistent": {"plugins.ml_commons.only_run_on_ml_node": False, "plugins.ml_commons.allow_registering_model_via_url": True, "plugins.ml_commons.trusted_connector_endpoints_regex": ["^http://127\\.0\\.0\\.1:18080/.*$"], "plugins.ml_commons.connector.private_ip_enabled": True, "plugins.ml_commons.agent_framework_enabled": True, "plugins.ml_commons.memory_feature_enabled": True}}
run(sys.argv[1:], "ml commons routes", "The stock ML Commons plugin's model group, connector, remote model, deploy, predict, train, execute, agent and memory routes. The remote model calls a local target (127.0.0.1:18080) that answers {\"out\":[1,2,3],\"echo\":\"ok\"} to any path starting /json. Local (ONNX or TorchScript) models are not recorded: they need model files.",
    steps, volatile=VOL, cleanup=cl,
    setup=[("PUT", "/_cluster/settings", settings), ("PUT", "/" + SRC, {"settings": {"number_of_shards": 1, "number_of_replicas": 0}}), ("POST", "/" + SRC + "/_bulk", None, {"refresh": "true"}, nd)],
    setup_note=f"cluster settings: {json.dumps(settings['persistent'])}; index {SRC}: 40 documents with numeric x, y and keyword g")
